1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const BASE_POINTS = 1;
7	const COMPANION_POINTS = 1;
8	const BONUS_POINTS_PER_EXTRA_TYPE = 2;
9	
10	/**
11	 * A Sphinx scores a bonus once the army fields more than four distinct monster
12	 * types counting itself — i.e. more than three distinct types among the cards
13	 * beside it. Expressed here from the scoring Sphinx's point of view, since a
14	 * second Sphinx counts as one of those companion types.
15	 */
16	const COMPANION_TYPES_BEFORE_BONUS = 3;
17	
18	const isSphinx = (card: Card): boolean => card.monster === "sphinx";
19	
20	/** Rank variants (e.g. Undead Warrior 1/2/3) are the same monster type. */
21	const countMonsterTypes = (cards: Card[]): number =>
22	  new Set(cards.map((card) => card.monster)).size;
23	
24	const extraTypesBeyondBonusThreshold = (companionTypes: number): number =>
25	  Math.max(0, companionTypes - COMPANION_TYPES_BEFORE_BONUS);
26	
27	const scoreForOneSphinx = (companionTypes: number): number => {
28	  const extraTypes = extraTypesBeyondBonusThreshold(companionTypes);
29	  return extraTypes === 0
30	    ? BASE_POINTS + COMPANION_POINTS
31	    : BASE_POINTS + BONUS_POINTS_PER_EXTRA_TYPE * extraTypes;
32	};
33	
34	const cardsBeside = (army: Card[], index: number): Card[] =>
35	  army.filter((_, other) => other !== index);
36	
37	export const scoreArmy = (army: Card[]): number =>
38	  army.reduce(
39	    (score, card, index) =>
40	      isSphinx(card)
41	        ? score + scoreForOneSphinx(countMonsterTypes(cardsBeside(army, index)))
42	        : score,
43	    0,
44	  );
